.device-setup-layout {
  display: grid;
  grid-template-columns: minmax(230px, 0.7fr) minmax(0, 1.3fr);
  gap: 24px;
  margin-top: 24px;
}

.wifi-status-panel {
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface-soft);
  padding: 20px;
}

.wifi-status-line {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 15px 0 10px;
}

.wifi-status-icon {
  flex: 0 0 11px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 0 4px var(--amber-soft);
}

#wifi {
  color: var(--amber);
  font-size: 1.12rem;
}

.wifi-status-panel:has(#wifi[data-state="connected"]) .wifi-status-icon {
  background: var(--success);
  box-shadow: 0 0 0 4px var(--success-soft);
}

#wifi[data-state="connected"] {
  color: var(--success);
}

.wifi-status-panel:has(#wifi[data-state="disconnected"]) .wifi-status-icon {
  background: var(--danger);
  box-shadow: 0 0 0 4px var(--danger-soft);
}

#wifi[data-state="disconnected"] {
  color: var(--danger);
}

.wifi-status-panel > p:last-child {
  margin: 0;
  color: var(--muted);
  font-size: 0.86rem;
}

.setup-guide {
  min-width: 0;
}

.setup-steps {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 20px;
  margin: 14px 0 0;
  padding: 0;
  counter-reset: wifi-step;
  list-style: none;
}

.setup-steps li {
  position: relative;
  display: grid;
  min-width: 0;
  gap: 3px;
  padding: 0 0 13px 40px;
  border-bottom: 1px solid var(--border);
  counter-increment: wifi-step;
}

.setup-steps li::before {
  content: counter(wifi-step);
  position: absolute;
  top: 1px;
  left: 0;
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1px solid #b7c8c1;
  border-radius: 50%;
  background: var(--primary-soft);
  color: var(--primary-hover);
  font-size: 0.78rem;
  font-weight: 800;
}

.setup-steps strong {
  color: var(--ink-strong);
  line-height: 1.4;
}

.setup-steps span {
  color: var(--muted);
  font-size: 0.86rem;
}

.setup-steps code,
.privacy-note code {
  border-radius: 5px;
  background: var(--surface-muted);
  color: var(--primary-hover);
  padding: 2px 5px;
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 0.88em;
  font-weight: 700;
  white-space: nowrap;
}

.privacy-note {
  margin: 16px 0 0;
  border-left: 3px solid var(--primary);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  background: var(--primary-soft);
  color: var(--muted-strong);
  padding: 12px 14px;
  font-size: 0.84rem;
}

.privacy-note strong {
  color: var(--primary-hover);
}

.section-heading {
  display: block;
}

.section-index {
  display: none;
}

.section-copy {
  max-width: 660px;
  margin: 0;
  font-size: 0.93rem;
}

.form-stack {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 24px;
}

.form-stack .field:first-child,
.form-stack .auth-actions {
  grid-column: 1 / -1;
}

.field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 6px;
}

.field-label,
.control-group-label,
.status-label {
  color: var(--muted-strong);
  font-size: 0.88rem;
  font-weight: 750;
}

.field-hint {
  margin: -2px 0 2px;
  font-size: 0.8rem;
}

input,
textarea,
select {
  width: 100%;
  min-height: 48px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background: #fff;
  color: var(--ink);
  padding: 11px 13px;
  transition: border-color 150ms ease, box-shadow 150ms ease, background 150ms ease;
}

textarea {
  min-height: 108px;
  resize: vertical;
}

input::placeholder,
textarea::placeholder {
  color: var(--muted);
}

input:hover,
textarea:hover,
select:hover {
  border-color: #9eaaa4;
}

input:focus,
textarea:focus,
select:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 4px var(--primary-soft);
  outline: none;
}

.auth-actions,
.auth-footer,
.settings-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.button {
  display: inline-flex;
  min-height: 46px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid transparent;
  border-radius: 11px;
  padding: 10px 17px;
  font-weight: 780;
  line-height: 1.2;
  transition: transform 140ms ease, background 140ms ease, border-color 140ms ease, box-shadow 140ms ease;
}

.button:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 7px 16px rgba(41, 50, 46, 0.11);
}

.button:active:not(:disabled) {
  transform: translateY(0);
}

.button:disabled {
  opacity: 0.5;
}

.button--primary,
.button--claim {
  background: var(--primary);
  color: #fff;
}

.button--primary:hover:not(:disabled),
.button--claim:hover:not(:disabled) {
  background: var(--primary-hover);
}

.button--secondary {
  border-color: var(--border-strong);
  background: #fff;
  color: var(--ink-strong);
}

.button--secondary:hover:not(:disabled) {
  border-color: #9eaaa4;
  background: var(--surface-soft);
}

.button--danger {
  border-color: #dfbaba;
  background: var(--danger-soft);
  color: var(--danger-hover);
}

.button--danger:hover:not(:disabled) {
  border-color: var(--danger);
  background: #f8dddd;
}

.button-arrow {
  font-size: 1.15em;
}

.auth-footer {
  margin-top: 15px;
}

.message {
  min-height: 1.5em;
  margin: 10px 0 0;
  color: var(--muted-strong);
  font-size: 0.88rem;
  overflow-wrap: anywhere;
}

.claim-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 10px;
  margin-top: 24px;
}

.button--claim {
  min-width: 132px;
}

.message--claim {
  min-height: 0;
  margin-top: 9px;
  border-radius: var(--radius-sm);
  padding: 0;
}

.message--claim:empty {
  display: none;
}

.message--claim:not(:empty) {
  padding: 9px 11px;
}

.message--claim[data-state="pending"] {
  background: var(--amber-soft);
  color: var(--amber);
}

.message--claim[data-state="success"] {
  background: var(--success-soft);
  color: var(--success);
}

.message--claim[data-state="error"] {
  background: var(--danger-soft);
  color: var(--danger-hover);
}

.locker-selector {
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid var(--border);
}

.locker-hint {
  margin-top: 7px;
}

.status-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.freshness-key {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  border-radius: 9px;
  background: var(--surface-soft);
  color: var(--muted-strong);
  padding: 8px 10px;
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
}

.freshness-key span {
  width: 8px;
  height: 8px;
}

.status-rail {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  margin-top: 24px;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface-soft);
}

.status-cell {
  position: relative;
  min-width: 0;
  min-height: 126px;
  padding: 20px 16px 17px;
  border-right: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.55);
}

.status-cell:last-child {
  border-right: 0;
}

.status-icon {
  display: block;
  width: 10px;
  height: 10px;
  margin-bottom: 15px;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 0 4px var(--amber-soft);
}

.status-cell strong {
  display: block;
  margin-top: 7px;
  color: var(--amber);
  font-size: 1rem;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.status-cell:has(strong[data-state="connected"]) .status-icon,
.status-cell:has(strong[data-state="online"]) .status-icon,
.status-cell:has(strong[data-state="closed"]) .status-icon,
.status-cell:has(strong[data-state="locked"]) .status-icon {
  background: var(--success);
  box-shadow: 0 0 0 4px var(--success-soft);
}

.status-cell strong[data-state="connected"],
.status-cell strong[data-state="online"],
.status-cell strong[data-state="closed"],
.status-cell strong[data-state="locked"] {
  color: var(--success);
}

.status-cell:has(strong[data-state="disconnected"]) .status-icon,
.status-cell:has(strong[data-state="offline"]) .status-icon,
.status-cell:has(strong[data-state="active"]) .status-icon {
  background: var(--danger);
  box-shadow: 0 0 0 4px var(--danger-soft);
}

.status-cell strong[data-state="disconnected"],
.status-cell strong[data-state="offline"],
.status-cell strong[data-state="active"] {
  color: var(--danger);
}

.status-cell:has(strong[data-state="open"]) .status-icon,
.status-cell:has(strong[data-state="unlocked"]) .status-icon,
.status-cell:has(strong[data-state="on"]) .status-icon {
  background: var(--blue);
  box-shadow: 0 0 0 4px var(--blue-soft);
}

.status-cell strong[data-state="open"],
.status-cell strong[data-state="unlocked"],
.status-cell strong[data-state="on"] {
  color: var(--blue);
}

.status-cell:has(strong[data-state="inactive"]) .status-icon,
.status-cell:has(strong[data-state="off"]) .status-icon {
  background: #88928e;
  box-shadow: 0 0 0 4px #ecefed;
}

.status-cell strong[data-state="inactive"],
.status-cell strong[data-state="off"] {
  color: var(--muted-strong);
}

.status-meta-grid {
  display: grid;
  grid-template-columns: minmax(240px, 0.65fr) minmax(0, 1.35fr);
  gap: 12px;
  margin-top: 12px;
}

.status-meta {
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-soft);
  padding: 13px 15px;
}

.status-meta strong {
  display: block;
  margin-top: 4px;
  color: var(--ink);
  font-size: 0.87rem;
  font-weight: 650;
  overflow-wrap: anywhere;
}

.message--state,
.message--command {
  margin-top: 14px;
  border-radius: var(--radius-sm);
  background: var(--primary-soft);
  color: var(--primary-hover);
  padding: 11px 13px;
}

.controls {
  display: grid;
  gap: 18px;
  margin-top: 24px;
}

.control-group {
  display: grid;
  gap: 8px;
}

.control-buttons {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.control-button {
  position: relative;
  min-height: 52px;
  border: 1px solid #b7c8c1;
  border-radius: 11px;
  background: var(--primary-soft);
  color: var(--primary-hover);
  padding: 11px 14px;
  font-weight: 800;
  transition: transform 140ms ease, background 140ms ease, box-shadow 140ms ease;
}

.control-button--open {
  border-color: #c7d3e2;
  background: var(--blue-soft);
  color: #28558f;
}

.control-button--alarm {
  border-color: #e2bcbc;
  background: var(--danger-soft);
  color: var(--danger-hover);
}

.control-button:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 7px 16px rgba(41, 50, 46, 0.1);
}

.control-button:disabled {
  border-color: var(--border);
  background: var(--surface-muted);
  color: #8b9591;
}

.control-button[data-pending="true"] {
  color: transparent;
}

.control-button[data-pending="true"]::after {
  color: var(--primary);
}

.control-button[data-pending="true"]::after,
form[data-pending="true"] .button[type="submit"]::after {
  content: "";
  position: absolute;
  width: 17px;
  height: 17px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: spin 700ms linear infinite;
}

.chat-form {
  display: grid;
  gap: 12px;
  margin-top: 24px;
}

.chat-submit {
  justify-self: start;
}

.answer-shell {
  margin-top: 18px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface-soft);
  padding: 16px;
}

#answer {
  min-height: 112px;
  margin: 9px 0 0;
  color: var(--ink);
  font-family: inherit;
  font-size: 0.92rem;
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.data-card,
.settings-card {
  min-height: 100%;
}

.settings-card {
  grid-column: 1 / -1;
}

.data-toolbar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
  margin-top: 22px;
}

.field--compact {
  min-width: 170px;
}

.history-list {
  min-height: 230px;
  max-height: 360px;
  margin: 16px 0 0;
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface-soft);
  color: var(--ink);
  padding: 18px;
  font-size: 0.9rem;
  line-height: 1.65;
  white-space: pre-line;
  overflow-wrap: anywhere;
}

.chart-plot {
  position: relative;
}

.chart-summary {
  margin: 22px 0 12px;
  color: var(--muted-strong);
  font-size: 0.9rem;
}

.chart-bars {
  display: flex;
  min-height: 230px;
  align-items: end;
  gap: 8px;
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background:
    linear-gradient(to top, transparent 24%, rgba(198, 206, 200, 0.45) 25%, transparent 26%, transparent 49%, rgba(198, 206, 200, 0.45) 50%, transparent 51%, transparent 74%, rgba(198, 206, 200, 0.45) 75%, transparent 76%),
    var(--surface-soft);
  padding: 24px 14px 32px;
}

.empty-state {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  margin: 0;
  color: var(--muted);
  padding: 24px;
  text-align: center;
  pointer-events: none;
}

.empty-state[hidden] {
  display: none;
}

.chart-day {
  display: grid;
  grid-template-columns: repeat(2, 8px);
  align-items: end;
  justify-content: center;
  gap: 3px;
  min-width: 30px;
  height: 178px;
}

.chart-bar {
  display: block;
  min-height: 0;
  border-radius: 4px 4px 1px 1px;
}

.chart-bar--open { background: var(--primary); }
.chart-bar--alert { background: var(--danger); }

.chart-label {
  grid-column: 1 / -1;
  transform: rotate(-50deg);
  transform-origin: top center;
  color: var(--muted);
  font-size: 0.66rem;
  white-space: nowrap;
}

.chart-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
  margin-top: 12px;
  color: var(--muted-strong);
  font-size: 0.82rem;
}

.chart-legend span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.chart-legend i {
  width: 11px;
  height: 11px;
  border-radius: 3px;
}

.legend-open { background: var(--primary); }
.legend-alert { background: var(--danger); }

.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  overflow: hidden !important;
  clip: rect(0 0 0 0) !important;
  clip-path: inset(50%) !important;
  white-space: nowrap !important;
}

.settings-form {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px 18px;
  margin-top: 24px;
}

.telegram-connection {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-soft);
}

.telegram-connection[data-connected="true"] {
  border-color: color-mix(in srgb, var(--primary) 42%, var(--border));
  background: color-mix(in srgb, var(--primary) 6%, var(--surface));
}

.telegram-connection .field-hint {
  margin: 5px 0 0;
}

.telegram-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.check-field {
  display: flex;
  min-height: 48px;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-soft);
  color: var(--ink);
  padding: 10px 12px;
  font-weight: 700;
  cursor: pointer;
}

.check-field input {
  width: 20px;
  min-height: 20px;
  height: 20px;
  margin: 0;
  accent-color: var(--primary);
}

.check-field:has(input:disabled) {
  cursor: not-allowed;
  opacity: 0.62;
}

.conditional-field {
  transition: opacity 140ms ease;
}

.conditional-field[data-enabled="false"] {
  opacity: 0.62;
}

.conditional-field input:disabled {
  background: var(--surface-muted);
  color: var(--muted);
  cursor: not-allowed;
}

.settings-actions {
  grid-column: 1 / -1;
}

form[data-pending="true"] {
  cursor: progress;
}

form[data-pending="true"] > * {
  pointer-events: none;
}

form[data-pending="true"] .button[type="submit"] {
  position: relative;
  color: transparent;
}

form[data-pending="true"] .button[type="submit"]::after {
  color: var(--primary);
}

.button--primary[data-pending="true"]::after,
form[data-pending="true"] .button--primary::after,
form[data-pending="true"] .button--claim::after {
  color: #fff;
}

.button[data-pending="true"] {
  position: relative;
  color: transparent;
  pointer-events: none;
}

.button[data-pending="true"]::after {
  content: "";
  position: absolute;
  width: 17px;
  height: 17px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: spin 700ms linear infinite;
}

.button--secondary[data-pending="true"]::after {
  color: var(--primary);
}

.page-footer {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  margin-top: 24px;
  padding: 18px 4px 0;
  border-top: 1px solid var(--border);
  font-size: 0.78rem;
}

.page-footer p {
  margin: 0;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@media (max-width: 1050px) {
  .identity-grid,
  .action-grid {
    grid-template-columns: 1fr;
  }

  .status-rail {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .status-cell:nth-child(3) {
    border-right: 0;
  }

  .status-cell:nth-child(-n + 3) {
    border-bottom: 1px solid var(--border);
  }
}

@media (max-width: 820px) {
  .app-shell {
    width: min(100% - 28px, 720px);
    padding-top: 26px;
  }

  .topbar {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }

  .session-panel {
    width: 100%;
  }

  .data-grid {
    grid-template-columns: 1fr;
  }

  .device-setup-layout {
    grid-template-columns: 1fr;
  }

  .settings-card {
    grid-column: auto;
  }

  .settings-form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 620px) {
  .app-shell {
    width: min(100% - 20px, 560px);
    padding-top: 18px;
  }

  .brand-mark {
    flex-basis: 48px;
    width: 48px;
    height: 56px;
  }

  .brand-mark span {
    left: 11px;
  }

  .auth-card,
  .ownership-card,
  .control-card,
  .chat-card,
  .device-setup-card,
  .data-card,
  .settings-card,
  .status-console {
    padding: 21px 18px;
    border-radius: 17px;
  }

  .form-stack,
  .settings-form {
    grid-template-columns: 1fr;
  }

  .telegram-connection {
    align-items: stretch;
    flex-direction: column;
  }

  .telegram-actions {
    justify-content: stretch;
  }

  .telegram-actions .button {
    flex: 1 1 100%;
  }

  .setup-steps {
    grid-template-columns: 1fr;
  }

  .form-stack .field:first-child,
  .form-stack .auth-actions,
  .settings-actions {
    grid-column: auto;
  }

  .status-header {
    flex-direction: column;
  }

  .freshness-key {
    white-space: normal;
  }

  .status-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .status-cell,
  .status-cell:nth-child(3) {
    border-right: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
  }

  .status-cell:nth-child(even) {
    border-right: 0;
  }

  .status-cell:nth-last-child(-n + 2) {
    border-bottom: 0;
  }

  .status-meta-grid {
    grid-template-columns: 1fr;
  }

  .claim-form,
  .data-toolbar {
    display: grid;
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .button--claim,
